package com.chubb.apac.claims.modulith.claim.api;import com.chubb.apac.claims.modulith.claim.model.Claim;import com.chubb.apac.claims.modulith.claim.repository.*;import com.chubb.apac.claims.modulith.common.enums.*;import com.chubb.apac.claims.modulith.common.exception.ConflictException;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.context.ApplicationEventPublisher;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ClaimWorkflowApiImplTest{@Test void rejectsWrongExpectedState(){ClaimRepository repo=mock(ClaimRepository.class);Claim c=new Claim();c.setClaimId("CLM-1");c.setStatus(ClaimStatus.REPORTED);c.setMarket(Market.SG);when(repo.findForUpdate("CLM-1",Set.of(Market.SG))).thenReturn(Optional.of(c));var api=new ClaimWorkflowApiImpl(repo,mock(ClaimStatusHistoryRepository.class),mock(ApplicationEventPublisher.class));assertThatThrownBy(()->api.transition("CLM-1",Set.of(Market.SG),ClaimStatus.UNDER_REVIEW,ClaimStatus.READY_FOR_DECISION,"x","S1","C1")).isInstanceOf(ConflictException.class);}}
